export async function createScene(context) {
  const T = context.THREE;
  const canvas = context.canvas;
  const input = context.input;
  const vp = context.viewport || { width: 360, height: 640 };
  let width = Math.max(1, vp.width || 1);
  let height = Math.max(1, vp.height || 1);
  const renderer = new T.WebGLRenderer({ canvas: canvas, antialias: true, alpha: false, powerPreference: 'high-performance' });
  renderer.setPixelRatio(Math.min(2, vp.pixelRatio || 1));
  renderer.setSize(width, height, false);
  renderer.outputColorSpace = T.SRGBColorSpace;
  renderer.toneMapping = T.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.12;
  const scene = new T.Scene();
  scene.background = new T.Color(0x02051a);
  const camera = new T.PerspectiveCamera(48, width / height, 0.1, 600);
  const ambient = new T.AmbientLight(0x365082, 0.5);
  scene.add(ambient);
  const sunLight = new T.PointLight(0xffcc66, 2.6, 0, 0);
  scene.add(sunLight);
  function rng(seed) {
    let s = seed >>> 0;
    return function() {
      s = (s + 0x6D2B79F5) >>> 0;
      let t = s;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function cl(v) {
    return v < 0 ? 0 : (v > 255 ? 255 : Math.round(v));
  }
  function surfaceTexture(kind) {
    const w = 128;
    const h = 64;
    const data = new Uint8Array(w * h * 4);
    const blobs = [
      { lon: -1.0, lat: 0.42, rx: 0.62, ry: 0.42 },
      { lon: -2.1, lat: -0.25, rx: 0.34, ry: 0.55 },
      { lon: -0.25, lat: 0.12, rx: 0.5, ry: 0.4 },
      { lon: 0.55, lat: -0.15, rx: 0.46, ry: 0.64 },
      { lon: 1.9, lat: 0.46, rx: 0.9, ry: 0.45 },
      { lon: 2.9, lat: -0.38, rx: 0.42, ry: 0.3 }
    ];
    for (let y = 0; y < h; y++) {
      const lat = (y / (h - 1) - 0.5) * Math.PI;
      for (let x = 0; x < w; x++) {
        const lon = (x / w) * Math.PI * 2;
        let r = 0;
        let g = 0;
        let b = 0;
        if (kind === 'earth') {
          let mass = 0;
          for (let i = 0; i < blobs.length; i++) {
            const bp = blobs[i];
            let dl = Math.abs(lon - bp.lon);
            if (dl > Math.PI) dl = Math.PI * 2 - dl;
            const q = (dl / bp.rx) * (dl / bp.rx) + ((lat - bp.lat) / bp.ry) * ((lat - bp.lat) / bp.ry);
            mass += Math.exp(-q * 2.1);
          }
          const noise = 0.12 * Math.sin(lon * 5.2 + lat * 6.7) + 0.08 * Math.sin(lon * 11.3 - lat * 4.1) + 0.05 * Math.cos(lon * 19.7 + lat * 8.9);
          if (Math.abs(lat) > 1.35) {
            r = 228; g = 239; b = 246;
          } else if (mass + noise > 0.6) {
            const shade = 0.5 + 0.5 * Math.sin(lon * 7.0 + lat * 3.0);
            r = 36 + 22 * shade; g = 112 + 56 * shade; b = 48 + 24 * shade;
          } else {
            const n2 = 0.5 + 0.5 * Math.sin(lon * 9.0 + lat * 13.0);
            r = 12 + 7 * n2; g = 48 + 24 * n2; b = 108 + 42 * n2;
          }
        } else if (kind === 'mars') {
          const n = 0.5 + 0.5 * Math.sin(lon * 4.1 + lat * 7.3) + 0.28 * Math.sin(lon * 9.7 - lat * 2.9) + 0.12 * Math.cos(lon * 17.0 + lat * 11.1);
          const t = Math.max(0, Math.min(1, n * 0.4 + 0.45));
          r = 126 + 68 * t; g = 51 + 31 * t; b = 27 + 17 * t;
          if (Math.abs(lat) > 1.47) { r = 202; g = 182; b = 158; }
          if (Math.sin(lon * 6.0 + lat * 10.0) > 0.82) { r *= 0.72; g *= 0.68; b *= 0.65; }
        } else if (kind === 'jupiter') {
          const turb = 0.35 * Math.sin(lon * 2.6 + lat * 7.4) + 0.18 * Math.sin(lon * 7.1 - lat * 3.2);
          const band = 0.5 + 0.5 * Math.sin(lat * 12.5 + turb);
          r = 184 + 48 * band; g = 131 + 43 * band; b = 81 + 27 * band;
          if (band < 0.22) { r = 148; g = 98; b = 61; }
        } else if (kind === 'saturn') {
          const band = 0.5 + 0.5 * Math.sin(lat * 9.5 + 0.3 * Math.sin(lon * 4.0 + lat * 8.0));
          r = 214 + 26 * band; g = 188 + 29 * band; b = 134 + 31 * band;
        } else if (kind === 'uranus') {
          const band = 0.5 + 0.5 * Math.sin(lat * 7.0 + 0.4 * Math.sin(lon * 3.0));
          r = 96 + 18 * band; g = 204 + 25 * band; b = 214 + 20 * band;
        } else if (kind === 'neptune') {
          const band = 0.5 + 0.5 * Math.sin(lat * 8.0 + 0.3 * Math.sin(lon * 4.5));
          r = 34 + 18 * band; g = 66 + 38 * band; b = 176 + 40 * band;
        } else if (kind === 'venus') {
          const n = 0.5 + 0.5 * Math.sin(lat * 6.2 + 0.5 * Math.sin(lon * 3.3));
          r = 220 + 18 * n; g = 186 + 25 * n; b = 124 + 18 * n;
        } else {
          const n = 0.5 + 0.5 * Math.sin(lon * 5.1 + lat * 8.1) + 0.22 * Math.cos(lon * 13.0 - lat * 4.0);
          r = 110 + 32 * n; g = 102 + 28 * n; b = 92 + 24 * n;
          if (n < 0.34) { r = 70; g = 67; b = 63; }
        }
        const idx = (y * w + x) * 4;
        data[idx] = cl(r);
        data[idx + 1] = cl(g);
        data[idx + 2] = cl(b);
        data[idx + 3] = 255;
      }
    }
    const tex = new T.DataTexture(data, w, h, T.RGBAFormat);
    tex.colorSpace = T.SRGBColorSpace;
    tex.wrapS = T.RepeatWrapping;
    tex.wrapT = T.ClampToEdgeWrapping;
    tex.minFilter = T.LinearFilter;
    tex.magFilter = T.LinearFilter;
    tex.needsUpdate = true;
    return tex;
  }
  function glowTexture() {
    const s = 64;
    const data = new Uint8Array(s * s * 4);
    for (let y = 0; y < s; y++) {
      for (let x = 0; x < s; x++) {
        const dx = (x + 0.5) / s * 2 - 1;
        const dy = (y + 0.5) / s * 2 - 1;
        const rr = Math.sqrt(dx * dx + dy * dy);
        const a = rr >= 1 ? 0 : Math.pow(1 - rr, 2.3);
        const idx = (y * s + x) * 4;
        data[idx] = 255;
        data[idx + 1] = 210;
        data[idx + 2] = 110;
        data[idx + 3] = cl(a * 255);
      }
    }
    const tex = new T.DataTexture(data, s, s, T.RGBAFormat);
    tex.colorSpace = T.SRGBColorSpace;
    tex.needsUpdate = true;
    return tex;
  }
  function ringTexture() {
    const w = 64;
    const data = new Uint8Array(w * 4);
    for (let i = 0; i < w; i++) {
      const t = i / (w - 1);
      let a = 0.22 + 0.78 * Math.pow(Math.sin(Math.PI * t), 0.55);
      if (t < 0.06 || t > 0.96) a = 0;
      if (t > 0.60 && t < 0.66) a *= 0.22;
      if (t > 0.38 && t < 0.43) a *= 0.38;
      const shade = 0.78 + 0.22 * Math.sin(t * 41.0);
      const copper = Math.pow(Math.max(0, Math.sin((t - 0.08) * Math.PI * 2.2)), 2.0);
      data[i * 4] = cl(255 * shade);
      data[i * 4 + 1] = cl((243 - 78 * copper) * (0.9 + 0.1 * shade));
      data[i * 4 + 2] = cl((207 - 132 * copper) * (0.88 + 0.12 * shade));
      data[i * 4 + 3] = cl(a * 255);
    }
    const tex = new T.DataTexture(data, w, 1, T.RGBAFormat);
    tex.colorSpace = T.SRGBColorSpace;
    tex.wrapS = T.ClampToEdgeWrapping;
    tex.wrapT = T.ClampToEdgeWrapping;
    tex.minFilter = T.LinearFilter;
    tex.magFilter = T.LinearFilter;
    tex.needsUpdate = true;
    return tex;
  }
  const texCache = {};
  function planetMaterial(kind) {
    if (!texCache[kind]) texCache[kind] = surfaceTexture(kind);
    return new T.MeshStandardMaterial({ map: texCache[kind], roughness: 0.88, metalness: 0.0 });
  }
  function makeStars(count, minR, maxR, seed, size) {
    const rand = rng(seed);
    const pos = [];
    const col = [];
    for (let i = 0; i < count; i++) {
      const u = rand() * 2 - 1;
      const theta = rand() * Math.PI * 2;
      const r = minR + rand() * (maxR - minR);
      const s = Math.sqrt(Math.max(0, 1 - u * u));
      pos.push(s * Math.cos(theta) * r, u * r, s * Math.sin(theta) * r);
      const tint = rand();
      col.push(0.65 + tint * 0.35, 0.72 + tint * 0.24, 0.9 + tint * 0.1);
    }
    const geo = new T.BufferGeometry();
    geo.setAttribute('position', new T.Float32BufferAttribute(pos, 3));
    geo.setAttribute('color', new T.Float32BufferAttribute(col, 3));
    const mat = new T.PointsMaterial({ size: size, vertexColors: true, transparent: true, opacity: 0.85, depthWrite: false, blending: T.AdditiveBlending, sizeAttenuation: true });
    const points = new T.Points(geo, mat);
    scene.add(points);
    return points;
  }
  const starsA = makeStars(900, 80, 180, 8675309, 0.55);
  const starsB = makeStars(220, 60, 170, 424242, 1.0);
  const starMatA = starsA.material;
  const starMatB = starsB.material;
  const sun = new T.Group();
  const sunMesh = new T.Mesh(new T.SphereGeometry(1.45, 32, 24), new T.MeshBasicMaterial({ color: 0xffcf55 }));
  sun.add(sunMesh);
  const halo = new T.Mesh(new T.SphereGeometry(1.8, 32, 24), new T.MeshBasicMaterial({ color: 0xffa53c, transparent: true, opacity: 0.15, blending: T.AdditiveBlending, depthWrite: false }));
  sun.add(halo);
  const sunGlow = new T.Sprite(new T.SpriteMaterial({ map: glowTexture(), color: 0xffbd55, transparent: true, opacity: 0.88, blending: T.AdditiveBlending, depthWrite: false }));
  sunGlow.scale.set(7.8, 7.8, 1);
  sun.add(sunGlow);
  scene.add(sun);
  function ringGeometry(inner, outer, segments) {
    const pos = [];
    const uv = [];
    const idx = [];
    for (let i = 0; i <= segments; i++) {
      const a = (i / segments) * Math.PI * 2;
      const c = Math.cos(a);
      const s = Math.sin(a);
      pos.push(c * inner, 0, s * inner);
      uv.push(0, 0.5);
      pos.push(c * outer, 0, s * outer);
      uv.push(1, 0.5);
    }
    for (let i = 0; i < segments; i++) {
      const a = i * 2;
      idx.push(a, a + 1, a + 2);
      idx.push(a + 1, a + 3, a + 2);
    }
    const geo = new T.BufferGeometry();
    geo.setAttribute('position', new T.Float32BufferAttribute(pos, 3));
    geo.setAttribute('uv', new T.Float32BufferAttribute(uv, 2));
    geo.setIndex(idx);
    return geo;
  }
  const defs = [
    { name: 'Mercury', orbit: 3.2, size: 0.15, speed: 0.52, start: 0.9, spin: 0.5, kind: 'mercury' },
    { name: 'Venus', orbit: 4.4, size: 0.22, speed: 0.34, start: 3.1, spin: -0.28, kind: 'venus' },
    { name: 'Earth', orbit: 5.7, size: 0.26, speed: 0.24, start: 5.3, spin: 0.9, kind: 'earth' },
    { name: 'Mars', orbit: 7.0, size: 0.2, speed: 0.17, start: 1.8, spin: 0.8, kind: 'mars' },
    { name: 'Jupiter', orbit: 8.6, size: 0.62, speed: 0.095, start: 0.25, spin: 1.4, kind: 'jupiter' },
    { name: 'Saturn', orbit: 10.1, size: 0.54, speed: 0.067, start: 2.25, spin: 1.2, kind: 'saturn' },
    { name: 'Uranus', orbit: 11.3, size: 0.4, speed: 0.047, start: 4.2, spin: 0.7, kind: 'uranus' },
    { name: 'Neptune', orbit: 12.4, size: 0.38, speed: 0.035, start: 5.35, spin: 0.75, kind: 'neptune' }
  ];
  const planets = {};
  const guideMat = new T.MeshBasicMaterial({ color: 0x6b8fd5, transparent: true, opacity: 0.1, depthWrite: false, side: T.DoubleSide });
  for (let i = 0; i < defs.length; i++) {
    const d = defs[i];
    const group = new T.Group();
    const sphere = new T.Mesh(new T.SphereGeometry(d.size, 32, 24), planetMaterial(d.kind));
    group.add(sphere);
    if (d.name === 'Saturn') {
      group.rotation.x = 0.12;
      group.rotation.z = -0.36;
      const ring = new T.Mesh(ringGeometry(d.size * 1.65, d.size * 2.55, 128), new T.MeshBasicMaterial({ map: ringTexture(), color: 0xfff2cf, transparent: true, opacity: 1.0, side: T.DoubleSide, depthWrite: false }));
      group.add(ring);
    } else if (d.name === 'Uranus') {
      group.rotation.z = 1.5;
    } else if (d.name === 'Neptune') {
      group.rotation.z = -0.28;
    }
    scene.add(group);
    const guide = new T.Mesh(new T.RingGeometry(d.orbit - 0.012, d.orbit + 0.012, 160), guideMat);
    guide.rotation.x = -Math.PI / 2;
    scene.add(guide);
    planets[d.name] = { group: group, sphere: sphere, orbit: d.orbit, speed: d.speed, start: d.start, spin: d.spin, angle: d.start };
  }
  function updateOrbits(time) {
    for (let i = 0; i < defs.length; i++) {
      const p = planets[defs[i].name];
      p.angle = p.start + p.speed * time;
      p.group.position.set(Math.cos(p.angle) * p.orbit, 0, Math.sin(p.angle) * p.orbit);
      p.sphere.rotation.y = time * p.spin + p.start;
    }
    sunMesh.rotation.y = time * 0.04;
    sunGlow.scale.setScalar(7.7 + 0.22 * Math.sin(time * 1.4));
    starMatA.opacity = 0.72 + 0.16 * Math.sin(time * 1.7);
    starMatB.opacity = 0.64 + 0.2 * Math.sin(time * 1.1 + 1.7);
  }
  function fitDistance() {
    const aspect = width / height;
    const halfV = (48 * Math.PI / 180) / 2;
    const halfH = Math.atan(Math.tan(halfV) * aspect);
    return Math.max(28, (13.45 / Math.tan(halfH)) * 1.07);
  }
  const currentState = Object.assign({}, context.state || {});
  if (typeof currentState.status !== 'string' || currentState.status.length === 0) currentState.status = 'System View';
  let mode = currentState.status === 'Saturn' ? 'saturn' : (currentState.status === 'Earth' ? 'earth' : (currentState.status === 'Jupiter' ? 'jupiter' : 'system'));
  function focusTarget(name) {
    return { yaw: name === 'Saturn' ? 0.82 : (name === 'Earth' ? 0.7 : 0.55), pitch: name === 'Saturn' ? 0.24 : (name === 'Earth' ? 0.18 : 0.12), radius: name === 'Saturn' ? 8.2 : (name === 'Earth' ? 2.2 : 2.6) };
  }
  const startFocus = mode === 'saturn' ? focusTarget('Saturn') : (mode === 'earth' ? focusTarget('Earth') : (mode === 'jupiter' ? focusTarget('Jupiter') : null));
  let yaw = startFocus ? startFocus.yaw : 0;
  let pitch = startFocus ? startFocus.pitch : 0.43;
  let radius = startFocus ? startFocus.radius : fitDistance();
  let targetYaw = yaw;
  let targetPitch = pitch;
  let targetRadius = radius;
  const origin = new T.Vector3(0, 0, 0);
  const lookPoint = new T.Vector3();
  const tempDir = new T.Vector3();
  let paused = false;
  let orbitTime = (Date.now() % 6000000) / 1000;
  let dragging = false;
  let dragId = null;
  let lastX = 0;
  let lastY = 0;
  function updateCamera(dt, snap) {
    const step = Math.max(0, Math.min(0.05, dt));
    const k = snap ? 1 : 1 - Math.exp(-step * 4.2);
    yaw += (targetYaw - yaw) * k;
    pitch += (targetPitch - pitch) * k;
    radius += (targetRadius - radius) * k;
    const wanted = mode === 'saturn' ? planets.Saturn.group.position : (mode === 'earth' ? planets.Earth.group.position : (mode === 'jupiter' ? planets.Jupiter.group.position : origin));
    if (snap) lookPoint.copy(wanted);
    else lookPoint.lerp(wanted, 1 - Math.exp(-step * 5.0));
    tempDir.set(Math.sin(yaw) * Math.cos(pitch), Math.sin(pitch), Math.cos(yaw) * Math.cos(pitch));
    camera.position.copy(lookPoint).addScaledVector(tempDir, radius);
    camera.lookAt(lookPoint);
    camera.updateMatrixWorld();
  }
  function setMode(next) {
    mode = next;
    if (next === 'saturn' || next === 'earth' || next === 'jupiter') {
      const name = next === 'saturn' ? 'Saturn' : (next === 'earth' ? 'Earth' : 'Jupiter');
      const f = focusTarget(name);
      currentState.status = name;
      targetYaw = f.yaw;
      targetPitch = f.pitch;
      targetRadius = f.radius;
    } else {
      currentState.status = 'System View';
      targetYaw = 0;
      targetPitch = 0.43;
      targetRadius = fitDistance();
    }
