  updateOrbits(orbitTime);
  updateCamera(0, true);
  renderer.render(scene, camera);
  function event(ev) {
    if (!ev) return;
    const type = ev.type;
    if (type === 'pointerdown') {
      dragging = true;
      dragId = ev.pointerId;
      lastX = ev.x;
      lastY = ev.y;
    } else if (type === 'pointermove') {
      if (!dragging || ev.pointerId !== dragId) return;
      const dx = ev.x - lastX;
      const dy = ev.y - lastY;
      lastX = ev.x;
      lastY = ev.y;
      targetYaw -= dx * 6.0;
      targetPitch = Math.max(0.08, Math.min(1.22, targetPitch + dy * 4.0));
    } else if (type === 'pointerup' || type === 'pointercancel') {
      dragging = false;
      dragId = null;
    } else if (type === 'action') {
      if (ev.actionId === 'focusSaturn') setMode('saturn');
      else if (ev.actionId === 'focusEarth') setMode('earth');
      else if (ev.actionId === 'focusJupiter') setMode('jupiter');
      else if (ev.actionId === 'systemView') setMode('system');
      updateOrbits(orbitTime);
      updateCamera(0, true);
      renderer.render(scene, camera);
    } else if (type === 'viewport') {
      width = Math.max(1, ev.width || width);
      height = Math.max(1, ev.height || height);
      renderer.setSize(width, height, false);
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      if (mode === 'system') targetRadius = fitDistance();
      updateCamera(0, true);
      renderer.render(scene, camera);
