      paused = true;
    } else if (type === 'resume' || type === 'start') {
      paused = false;
    } else if (type === 'restart') {
      paused = false;
    } else if (type === 'open') {
      updateOrbits(orbitTime);
      updateCamera(0, true);
      renderer.render(scene, camera);
    }
  }
  function frame(info) {
    if (paused) {
      renderer.render(scene, camera);
      return;
    }
    const raw = info && typeof info.dtMs === 'number' ? info.dtMs : 16.667;
    const dt = Math.max(0, Math.min(0.06, raw / 1000));
    orbitTime += dt;
    updateOrbits(orbitTime);
    updateCamera(dt, false);
    renderer.render(scene, camera);
  }
